using Finance.Application.Common;
using Finance.Domain.Categories;
using FluentValidation;

namespace Finance.Application.Features.Categories;

public record CategoryPayload
{
    public string? Name { get; init; }

    public CategoryKind? Kind { get; init; }

    public Guid? ParentId { get; init; }

    public string? Icon { get; init; }

    public string? Color { get; init; }

    public bool IsArchived { get; init; }
}

public sealed record CreateCategoryRequest : CategoryPayload
{
    /// <summary>Client-generated UUID v7. Generated by the server when omitted.</summary>
    public Guid? Id { get; init; }
}

/// <summary>A category as pulled; <see cref="SystemCode"/> is read-only.</summary>
public sealed record CategorySyncData : CategoryPayload
{
    public string? SystemCode { get; init; }
}

public sealed record CategoryResponse(
    Guid Id,
    string Name,
    CategoryKind Kind,
    Guid? ParentId,
    string? Icon,
    string? Color,
    bool IsArchived,
    string? SystemCode,
    long Version,
    DateTime CreatedAt,
    DateTime UpdatedAt)
{
    public static CategoryResponse From(Category c) => new(
        c.Id, c.Name, c.Kind, c.ParentId, c.Icon, c.Color, c.IsArchived, c.SystemCode, c.Version, c.CreatedAt, c.UpdatedAt);
}

internal sealed class CategoryPayloadValidator : AbstractValidator<CategoryPayload>
{
    public CategoryPayloadValidator()
    {
        RuleFor(x => x.Name).NotEmpty().MaximumLength(60);
        RuleFor(x => x.Kind).NotNull().IsInEnum();
        RuleFor(x => x.Icon).MaximumLength(50);
        RuleFor(x => x.Color).IsHexColor();
    }
}
